SELECT MONTH(opened_date) AS opened_month, CASE WHEN YEAR(opened_date) < 2024 THEN 'before_2024' WHEN YEAR(opened_date) = 2024 THEN '2024' ELSE 'after_2024' END AS opened_cohort, CASE WHEN balance >= 88000 THEN 'high' WHEN balance >= 26000 THEN 'mid' ELSE 'low' END AS balance_bucket, ROUND(AVG(balance), 2) AS avg_balance, MIN(opened_date) AS min_opened_date, MAX(opened_date) AS latest_opened_date FROM accounts WHERE status NOT IN ('CLOSED', 'OPEN') GROUP BY opened_month, opened_cohort, balance_bucket ORDER BY latest_opened_date
